{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.KA_US_AMAZON_FACT_ITEMS AS SELECT \'AMAZON US\' AS shop_name, \'US\' REGION, cast(amazon_order_id as string) order_id, cast(amazon_order_id AS string) order_name, NULL AS customer_id, NULL AS phone, NULL AS tags, NULL AS line_item_id, cast(Sku as string ) sku, ASIN AS product_id, cast(Currency as string) Currency, CASE WHEN order_status IN (\'Shipped - Returned to Seller\', \'Shipped - Returning to Seller\', \'Shipped - Rejected by Buyer\', \'Shipped - Damaged\') THEN 1 ELSE 0 END AS is_refund, cast(UPPER(ship_city) as string) AS city, cast(UPPER(ship_state) as string) AS state, cast(ship_postal_code as string) AS pincode, upper(cast(product_name as string)) AS product_name, NULL AS category, cast(order_status as string )order_status, DATETIME(PARSE_TIMESTAMP(\'%Y-%m-%dT%H:%M:%S%Ez\', purchase_date), \"America/Los_Angeles\") AS order_timestamp_PST, DATETIME(PARSE_TIMESTAMP(\'%Y-%m-%dT%H:%M:%S%Ez\', purchase_date),\"Asia/Kolkata\") AS order_timestamp, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) AS line_item_sales, IFNULL(SAFE_CAST(shipping_price AS FLOAT64), 0) AS shipping_price, IFNULL(SAFE_CAST(quantity AS FLOAT64), 0) AS quantity, IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) AS tax, SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0)) AS tax_rate, IFNULL(safe_CAST(item_promotion_discount AS FLOAT64), 0) AS discount, SAFE_DIVIDE(IFNULL(SAFE_CAST(item_promotion_discount AS FLOAT64), 0), (1 - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0))) )) AS discount_before_tax, NULL AS gross_sales_after_tax, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_promotion_discount AS FLOAT64), 0), (1 - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0))) ))) AS gross_sales_before_tax, NULL AS net_sales_before_tax, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) AS total_sales, \'Amazon US\' AS source, NULL AS landing_utm_medium, NULL AS landing_utm_source, NULL AS landing_utm_campaign, NULL AS referring_utm_medium, NULL AS referring_utm_source, NULL AS landing_utm_channel, NULL AS referring_utm_channel, NULL AS final_utm_channel, NULL AS new_customer_flag, NULL AS acquisition_channel, NULL AS acquisition_product, IFNULL(SAFE_CAST(shipping_tax AS FLOAT64), 0) AS shipping_tax, IFNULL(SAFE_CAST(ship_promotion_discount AS FLOAT64), 0) AS ship_promotion_discount, IFNULL(SAFE_CAST(gift_wrap_price AS FLOAT64), 0) AS gift_wrap_price, IFNULL(SAFE_CAST(gift_wrap_tax AS FLOAT64), 0) AS gift_wrap_tax ,timestamp(datetime(PARSE_TIMESTAMP(\'%Y-%m-%dT%H:%M:%S%Ez\', last_updated_date)),\"Asia/Kolkata\") last_updated_date FROM ( SELECT *, purchase_date AS Purchase_datetime_PDT FROM MAPLEMONK.KA_ASP_US_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL where not(lower(cast(amazon_order_id AS string)) like \'s0%\') ) X; CREATE OR REPLACE TABLE MAPLEMONK.KA_US_amazon_fact_items_TEMP_Category AS SELECT fi.* ,ifnull(quantity,0)*ifnull(p.MRP,0) MRP_SALES_INR ,case when ifnull(quantity,0)*ifnull(p.MRP,0) > fi.total_sales*coalesce(CM.USD_INR,83) then ifnull(quantity,0)*ifnull(p.MRP,0)-fi.total_sales*coalesce(CM.USD_INR,83) else 0 end MRP_Discount_INR ,fi.line_item_sales*coalesce(CM.USD_INR,83) line_item_sales_INR ,fi.total_sales*coalesce(CM.USD_INR,83) Total_Sales_INR ,fi.discount*coalesce(CM.USD_INR,83) Discount_INR ,fi.discount_before_tax*coalesce(CM.USD_INR,83) discount_before_tax_INR ,fi.gross_sales_after_tax*coalesce(CM.USD_INR,83) gross_sales_after_tax_INR ,fi.gross_sales_before_tax*coalesce(CM.USD_INR,83) gross_sales_before_tax_INR ,fi.net_sales_before_tax*coalesce(CM.USD_INR,83) net_sales_before_tax_INR ,fi.tax*coalesce(CM.USD_INR,83) Tax_INR ,fi.shipping_price*coalesce(CM.USD_INR,83) Shipping_Price_INR ,fi.shipping_tax*coalesce(CM.USD_INR,83) shipping_tax_INR ,fi.ship_promotion_discount*coalesce(CM.USD_INR,83) ship_promotion_discount_INR ,p.name AS product_name_final ,COALESCE(UPPER(cast(p.CATEGORY as string)), UPPER(cast(fi.category as string))) AS product_category ,UPPER(cast(p.sub_category as string)) AS product_sub_category ,p.tax_rate final_tax_rate ,p.commonsku commonsku ,cast(null as string) AS Email ,cast(null as string) AS Name ,cast(null as string) Recipient_Name FROM MAPLEMONK.KA_US_AMAZON_FACT_ITEMS fi left join (select MARKETPLACE_SKU skucode, name, category, category_code sub_category, category_code, MRP, commonsku, TAX_RATE from (select * from maplemonk.final_sku_master where upper(data_source) like \'AMAZON SELLER CENTRAL US\') qualify row_number() over (partition by lower(ifnull(trim(MARKETPLACE_SKU),\'\')) order by lower(ifnull(trim(COMMONSKU),\'\')) desc) = 1 ) p on lower(fi.sku) = lower(p.skucode) LEFT JOIN ( SELECT rate_date_ist AS date, rate AS USD_INR FROM `kerala-ayurveda-wh.MapleMonk.exchange_rates` WHERE base_currency = \'USD\' AND quote_currency = \'INR\' ) CM ON CAST(fi.order_timestamp AS DATE) = CM.date ; CREATE OR REPLACE TABLE MAPLEMONK.KA_US_AMAZON_FACT_ITEMS AS SELECT * FROM MAPLEMONK.KA_US_amazon_fact_items_TEMP_Category;",
                    "transaction": true
                }
            ) }}
